// === Tab: mySketch ===
// Inspired by https://thebookofshaders.com/edit.php#10/ikeda-03.frag - Ikeda Data Stream
// Made for sableRaph's weekly creative challenge 
// #WCCChallenge
// https://www.twitch.tv/sableraph


let streams = [];
let speeds = [];

let NUM_STREAMS = 30;
let MIN_STREAK = 4;
let GAP_MAX = 20
let ts = Array(NUM_STREAMS).fill(0);

function setup() {
	createCanvas(windowWidth, windowHeight);
	for (let i = 0; i < NUM_STREAMS; i++){

		let s = round(random(1, 5));
		speeds.push(s);

		let acc = [];
		let randCoeff = random(0.5, 1);
		for (let x = 0; x < width; x+=MIN_STREAK){
			if (random() > randCoeff) {
				let gapLen = random(MIN_STREAK, GAP_MAX);

				for (let k = 0; k < gapLen; k++){
					acc.push(false);
				}
				x += gapLen;
			}
			else {
				for (let k = 0; k < MIN_STREAK; k++) {
					acc.push(true);
				}
			}
		}
		streams.push(acc);
	}
}

function draw() {
	background(250);
	strokeWeight(6.5);
	strokeCap(SQUARE);
	noFill();
	let i = 0

	for (let y = 0; y < height - (height/NUM_STREAMS); y += height/NUM_STREAMS) {
		let begun = true;
		beginShape();
		let stream = streams[i];

		let speedMod = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1, 10);
		t = ts[i];
		ts[i] += speeds[i] * round(speedMod);

		let shift = y/200 + speedMod;
		let freq = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height*0.25, height*0.05);
		let getY = (xVal) => sin(xVal/freq - frameCount/3000 + shift) * height/NUM_STREAMS + y;

		for (let x = 0; x < width; x+=1){
			let val = stream[(x + t) % width];
			if (val && begun) {
				vertex(x, getY(x));
			} else if (val && !begun) {
				begun = true;
				beginShape();
				vertex(x, getY(x));
			} else if (!val && begun){
				endShape();
				begun = false;

				blendMode(BLEND);
			}
		}
		endShape();
		i += 1;
	}
}



// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
